    def test_full_gate_rejects_wrong_apk_sdk_run_attempt_and_engine_identity(self):
        for location,key,value in [('expectedBuildIdentity','apkSha256','f'*64),('expectedBuildIdentity','sourceTree','f'*40),('gecko','versionCode',102),('chromium','sourceCommit','f'*40),('sdk','runAttempt',2),('sdk','runId','999')]:
            with self.subTest(location=location,key=key),tempfile.TemporaryDirectory() as folder:
                report=self.document();expected=copy.deepcopy(report['expectedBuildIdentity'])
                selected=report[location] if location=='expectedBuildIdentity' else report['results'][location]['buildIdentity'] if location!='sdk' else report['results']['gecko']['buildIdentity']['sdkBuildIdentity'];selected[key]=value
                Path(folder,'browser-fingerprint-results.json').write_text(json.dumps(report))
                with self.assertRaises(ValueError):gate.verify_fingerprint_evidence(folder,'a'*40,expected,lambda source,path:b'controlled source')

    def test_strict_json_rejects_duplicate_fields_and_nonfinite_values(self):
        for raw in [b'{"status":"passed","status":"passed"}',b'{"value":NaN}']:
            with self.subTest(raw=raw),tempfile.TemporaryDirectory() as folder:
                Path(folder,'browser-fingerprint-results.json').write_bytes(raw)
                with self.assertRaises(ValueError):gate.verify_fingerprint_evidence(folder,'a'*40,{},lambda source,path:b'controlled source')


